/**
 * 微信只认 GIF：模型自己挑中的那张 `_stickers` 静态图，出站前先拿文件名当"感觉"去图库换一张真动图。
 * 换不到时按严格开关决定：严格 → 这张不发（宁可没表情也不发张不动的）；非严格 → 原样发。
 * @returns {Promise<{file: string, desc: string, reason: string, fromMeme: boolean}>} file 为空 = 这张别发
 */
async wechatAnimatedSwap(filePath, prefs = {}) {
	const strict = prefs.animatedStrict === true;
	const base = String(filePath ?? '').split(/[\\/]/).pop().replace(/\.[^.]+$/, '').trim();
	// 缓存文件名是 sha1（meme-72e90d42b9b5），拿它当「感觉」等于没给词：能用本轮挑图描述就用描述
	const seen = String(this.lastWechatSticker?.desc ?? '').trim();
	const feel = base === '' || /^meme-[0-9a-f]{6,}$/i.test(base) ? (seen !== '' ? seen : '日常') : base;
	// 换不到 / 出错都走这里：严格模式给个空 file（= 这张不发），非严格原样发
	const keep = (why) => (strict
		? { file: '', desc: feel, reason: why + '（严格模式：这张不发）', fromMeme: false }
		: { file: String(filePath ?? ''), desc: feel, reason: why, fromMeme: false });
	const meme = this.stickers?.meme ?? null;
	if (meme === null || typeof meme.pick !== 'function') return keep('没有表情包服务');
	try {
		const hit = await meme.pick({ feel, animatedFirst: true, animatedStrict: strict });
		const path = String(hit?.path ?? '');
		if (hit?.ok === true && /\.gif$/i.test(path) === true) {
			return { file: path, desc: String(hit.caption ?? hit.tag ?? feel), reason: '', fromMeme: true };
		}
		return keep(String(hit?.reason ?? '图库里没有这张的动图'));
	} catch (error) {
		return keep('换动图失败：' + String(error instanceof Error ? error.message : error));
	}
},

