 */
/**
 * 「微信·嘉新（主人）」这条会话到底通到哪儿（[FS-WECHAT-MASTER-GATE]）。
 * 面板上要能一眼看出：认人里填的主人 id 有没有对应会话、会话挂在哪个工作区（应该是「鱼」）、还活不活跃。
 */
/** dedicatedWorkspacePath 的安全包装：取不到就当空串，别让 /channels/state 整条 500 [FS-WECHAT-MASTER-GATE] */
const safeDedicatedWorkspace = () => { try { return String(dedicatedWorkspacePath() ?? ''); } catch { return ''; } };
const wechatMasterSession = (masterIds) => {
	const ids = Array.isArray(masterIds) ? masterIds.map((x) => String(x).trim()).filter(Boolean) : [];
	const blank = {
		linked: false, masterId: ids[0] ?? '', title: '', channelId: '', workspacePath: '', workspaceTitle: '',
		expectedWorkspace: safeDedicatedWorkspace(), status: '', lastInboundAt: 0, reason: '还没填主人微信 id（认人 → 主人）'
	};
	if (ids.length === 0) return blank;
	let row = null;
	try {
		const marks = ids.flatMap((id) => [`wechat:private:${id}`, `wechat-private:${id}`]);
		row = db.prepare(
			`SELECT * FROM chat_session WHERE channel = 'wechat' AND channel_id IN (${marks.map(() => '?').join(', ')}) ORDER BY COALESCE(last_inbound_at, created_at) DESC LIMIT 1`
		).get(...marks) ?? null;
	} catch (error) {
		logger('warn', '[fish-soul] 读微信主人会话失败：' + String(error instanceof Error ? error.message : error));
	}
	if (row === null) {
		return { ...blank, reason: '还没有「微信·嘉新（主人）」这条会话（主人还没在微信上跟她说过话，或者会话被归档了）' };
	}
	const workspacePath = String(row.workspace_path ?? '');
	let workspaceTitle = '';
	try {
		const hit = (gateway?.listWorkspaces?.() ?? []).find((one) => String(one.path ?? '').toLowerCase() === workspacePath.toLowerCase());
		workspaceTitle = String(hit?.title ?? '');
	} catch { workspaceTitle = ''; }
	const expected = safeDedicatedWorkspace();
	const onDedicated = expected !== '' && workspacePath.toLowerCase() === expected.toLowerCase();
	const state = {
		linked: row.status === 'active' && onDedicated,
		masterId: ids[0] ?? '',
		title: String(row.title ?? ''),
		channelId: String(row.channel_id ?? ''),
		workspacePath,
		workspaceTitle: workspaceTitle !== '' ? workspaceTitle : (onDedicated ? '鱼' : ''),
		expectedWorkspace: expected,
		status: String(row.status ?? ''),
		lastInboundAt: Number(row.last_inbound_at ?? 0) || 0,
		reason: ''
	};
	if (state.linked) return state;
	if (row.status !== 'active') state.reason = `会话状态是 ${state.status || '未知'}，不是 active（被归档 / 暂停了）`;
	else if (!onDedicated) state.reason = `会话挂在别的工作区（${workspacePath || '空'}），不是「鱼」`;
	else state.reason = '会话没联通';
	return state;
};

